{chain="클래식 수락 조건 참고 · 포에버 실제 NPC 제공 상태를 우선합니다.\n선행 중 하나: 공포의 요새 낙스라마스 / 공포의 요새 낙스라마스 / 공포의 요새 낙스라마스",dungeonKey="naxx",dungeonName="낙스라마스",faction="Both",inside=false,level=60,minLevel=60,npc="동부 역병지대 / 사령관 엘리고르 돈브링어",objective="동부 역병지대의 희망의 빛 예배당에 있는 사령관 엘리고르 돈브링어가 살아 움직이는 괴물 5마리, 돌가죽 가고일 5마리, 죽음의 기사단 대장 8명, 맹독 늑대거미 3마리를 처치해 달라고 했습니다.",prereqID=0,questID=9033,title="전쟁의 메아리"},
{chain="클래식 수락 조건 참고 · 포에버 실제 NPC 제공 상태를 우선합니다.",dungeonKey="naxx",dungeonName="낙스라마스",faction="Both",inside=false,level=60,minLevel=60,npc="켈투자드의 성물함",objective="동부 역병지대에 있는 희망의 빛 예배당에 켈투자드의 성물함을 가져가야 합니다.",prereqID=0,questID=9120,title="켈투자드의 죽음"},
{chain="클래식 수락 조건 참고 · 포에버 실제 NPC 제공 상태를 우선합니다.\n평판 조건이 있는 퀘스트입니다. NPC의 요구 평판·재료를 확인하세요.",dungeonKey="naxx",dungeonName="낙스라마스",faction="Both",inside=false,level=60,minLevel=60,npc="동부 역병지대 / 대마법사 안젤라 도산토스",objective="동부 역병지대의 희망의 빛 예배당에 있는 대마법사 안젤라 도산토스가 신비한 수정 5개, 마력의 결정체 2개, 정의의 보주 1개, 60골드를 가져다달라고 부탁했습니다. 또한 은빛 여명회의 평판이 우호적이어야 합니다.",prereqID=0,questID=9121,title="공포의 요새 낙스라마스"},
{chain="클래식 수락 조건 참고 · 포에버 실제 NPC 제공 상태를 우선합니다.\n평판 조건이 있는 퀘스트입니다. NPC의 요구 평판·재료를 확인하세요.",dungeonKey="naxx",dungeonName="낙스라마스",faction="Both",inside=false,level=60,minLevel=60,npc="동부 역병지대 / 대마법사 안젤라 도산토스",objective="동부 역병지대의 희망의 빛 예배당에 있는 대마법사 안젤라 도산토스가 신비한 수정 2개, 마력의 결정체 1개, 30골드를 가져다 달라고 부탁했습니다. 또한 은빛 여명회의 평판이 매우 우호적이어야 합니다.",prereqID=0,questID=9122,title="공포의 요새 낙스라마스"},
{chain="클래식 수락 조건 참고 · 포에버 실제 NPC 제공 상태를 우선합니다.\n평판 조건이 있는 퀘스트입니다. NPC의 요구 평판·재료를 확인하세요.",dungeonKey="naxx",dungeonName="낙스라마스",faction="Both",inside=false,level=60,minLevel=60,npc="동부 역병지대 / 대마법사 안젤라 도산토스",objective="동부 역병지대의 희망의 빛 예배당에 있는 대마법사 안젤라 도산토스가 비전 은신 마법으로 낙스라마스로 들어갈 수 있도록 해 줄 것입니다. 은빛 여명회의 평판이 확고한 동맹이어야 합니다.",prereqID=0,questID=9123,title="공포의 요새 낙스라마스"},
